import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BbQUUm7J.js";const c=JSON.parse('{"title":"Quantitative Algo Engines (furlpay algo)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/algorithms.md","filePath":"guide/algorithms.md","lastUpdated":1794862063000}'),n={name:"guide/algorithms.md"};function l(h,s,o,r,p,d){return a(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="quantitative-algo-engines-furlpay-algo" tabindex="-1">Quantitative Algo Engines (<code>furlpay algo</code>) <a class="header-anchor" href="#quantitative-algo-engines-furlpay-algo" aria-label="Permalink to &quot;Quantitative Algo Engines (`furlpay algo`)&quot;">​</a></h1><p>The research-driven analysis surface — every engine implements a formula from the <a href="https://github.com/FurlPay/furlpay-cli/blob/main/HFT_V2_Advanced_Algorithms_Live_Research_Report.md" target="_blank" rel="noreferrer">HFT V2 research report</a>, runs <strong>offline over data you supply</strong>, and fails closed on malformed input.</p><div class="warning custom-block"><p class="custom-block-title">Honesty scope</p><p>Schedules are <strong>plans</strong>, verdicts are <strong>arithmetic</strong>. Nothing here places, signs or broadcasts an order, and no live edge is ever claimed. When the WebSocket engine ships, it feeds these same pure engines.</p></div><h2 id="algo-quotes-—-glft-closed-form-quotes" tabindex="-1"><code>algo quotes</code> — GLFT closed-form quotes <a class="header-anchor" href="#algo-quotes-—-glft-closed-form-quotes" aria-label="Permalink to &quot;`algo quotes` — GLFT closed-form quotes&quot;">​</a></h2><p>The Guéant–Lehalle–Fernandez-Tapia model — the deployable quoting frontier per the 2026 literature (hftbacktest ships a full implementation), adding the ½γσ²τ volatility term that the Avellaneda-Stoikov variant omits:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>δa + δb = γσ²τ + (2/γ)·ln(1 + γ/k)      (total spread)</span></span>\n<span class="line"><span>r       = s − q·γσ²τ                     (inventory-skewed reservation)</span></span>\n<span class="line"><span>p(δ)    = e^(−kδ)                        (GLFT fill probability)</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quotes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mid</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6482150</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gamma</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sigma</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.02</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kappa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--inventory </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">q]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--time-left </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1]</span></span></code></pre></div><h2 id="algo-schedule-—-micro-twap-pov-execution-planning" tabindex="-1"><code>algo schedule</code> — micro-TWAP / POV execution planning <a class="header-anchor" href="#algo-schedule-—-micro-twap-pov-execution-planning" aria-label="Permalink to &quot;`algo schedule` — micro-TWAP / POV execution planning&quot;">​</a></h2><p>Poisson-jittered time slices (deterministic for a pinned <code>--seed</code>), sizes reconciling <strong>exactly</strong> to the parent amount in BigInt — no minor unit minted or lost. POV mode caps participation at <code>--cap</code> (default 3.5%) over a supplied per-minute volume profile and <strong>fails closed without one</strong> — the tool refuses to guess volume.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --amount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000000000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --duration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 900</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slices</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --amount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5000000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --duration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3600</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.035</span></span></code></pre></div><p>An incomplete POV plan (observed volume &lt; parent amount at the cap) reports the remainder — it never auto-chases the tail, because chasing the tail is how POV orders become impact events.</p><h2 id="algo-report-—-implementation-shortfall-scorecard" tabindex="-1"><code>algo report</code> — Implementation Shortfall scorecard <a class="header-anchor" href="#algo-report-—-implementation-shortfall-scorecard" aria-label="Permalink to &quot;`algo report` — Implementation Shortfall scorecard&quot;">​</a></h2><p>IS is measured against <strong>your arrival price</strong> — the only honest scorecard, since it&#39;s the decision price, not a mid the executor can pick. Exact BigInt accounting: <code>Σ size·(price − arrival)</code>, VWAP with the division remainder surfaced, fees in minor units and bps.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --arrival</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fills.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # [{ priceMinor, sizeMinor, feeMinor? }]</span></span></code></pre></div><h2 id="algo-breakeven-—-maker-ship-no-ship-arithmetic" tabindex="-1"><code>algo breakeven</code> — maker ship/no-ship arithmetic <a class="header-anchor" href="#algo-breakeven-—-maker-ship-no-ship-arithmetic" aria-label="Permalink to &quot;`algo breakeven` — maker ship/no-ship arithmetic&quot;">​</a></h2><p>The §7.1 objective function as a decision tool:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E[PnL/hour] = λ·(δ − a − c) − ½γσ²q²   (bps)</span></span></code></pre></div><p>λ is your <strong>observed</strong> fill rate at that spread — the fill-probability adjustment (arXiv:2502.18625) enters through λ: widening δ lowers λ, and the tool refuses to pretend otherwise.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> breakeven</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --half-spread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toxicity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fee</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --inventory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gamma</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sigma</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.02</span></span></code></pre></div><h2 id="algo-queue-—-fluid-queue-position-estimate" tabindex="-1"><code>algo queue</code> — fluid queue-position estimate <a class="header-anchor" href="#algo-queue-—-fluid-queue-position-estimate" aria-label="Permalink to &quot;`algo queue` — fluid queue-position estimate&quot;">​</a></h2><p>Transparent fluid model: the queue ahead drains at (trade rate + cancel rate). Estimates seconds-to-front and fill probability within your horizon. Useful for ALO quoting sanity — if the queue can&#39;t clear in your horizon, the quote is dead inventory. (Approximation, not the full Moallemi queue-value model.)</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ahead</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trade-rate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cancel-rate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --horizon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span></span></code></pre></div><h2 id="algo-funding-—-persistence-z-score-honest-carry" tabindex="-1"><code>algo funding</code> — persistence z-score + honest carry <a class="header-anchor" href="#algo-funding-—-persistence-z-score-honest-carry" aria-label="Permalink to &quot;`algo funding` — persistence z-score + honest carry&quot;">​</a></h2><p>Funding entry needs <strong>both</strong> a z-score above threshold (default 2.0) over your supplied ≥8-sample per-8h history and operator OI confirmation. A single high print is not a signal. Annualized gross uses <code>f̄·3·365</code>; the verdict reminds you that crowding compresses funding, both legs pay fees, and basis drift forces rebalances.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> funding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --history</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> funding.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --z</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fees</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span></code></pre></div><h2 id="algo-cascade-—-liquidation-cascade-regime-flag" tabindex="-1"><code>algo cascade</code> — liquidation-cascade regime flag <a class="header-anchor" href="#algo-cascade-—-liquidation-cascade-regime-flag" aria-label="Permalink to &quot;`algo cascade` — liquidation-cascade regime flag&quot;">​</a></h2><p>Composite of the three cascade signatures: funding spike (≥5 bps/8h), ask-wall OBI (≤ −0.65), toxic VPIN (≥ 0.75). Score ≥ 2 → <code>CASCADE-LIKELY</code> → reduce maker exposure.</p><div class="danger custom-block"><p class="custom-block-title">There is no sniping edge</p><p>Per the V2 report §5 correction: Hyperliquid routes liquidations through the book <strong>without discount</strong>; failed liquidations go to the HLP backstop (which you can participate in live via <a href="/furlpay-cli/guide/hyperliquid"><code>earn hlp</code></a>). The cascade tool is analysis only — every response carries this correction.</p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> algo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cascade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --funding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0006</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --obi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0.7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vpin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.8</span></span></code></pre></div><h2 id="mcp-exposure-read-only" tabindex="-1">MCP exposure (read-only) <a class="header-anchor" href="#mcp-exposure-read-only" aria-label="Permalink to &quot;MCP exposure (read-only)&quot;">​</a></h2><p>AI agents get the same math through three read-only tools: <code>algo_glft_quotes</code>, <code>algo_breakeven</code>, <code>algo_cascade</code> — annotated <code>readOnlyHint</code>, offline-labeled in every response. See <a href="/furlpay-cli/guide/agents">MCP Agents</a>.</p>',31)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
